// 這一回合派出的子代理：開新一批、記錄每次請求的模型與用量、思考與工具呼叫、完成與失敗。
// 全部是純函式，回傳新物件、不改傳入的 batch；找不到子代理時原樣回傳同一個物件
import type { AgentRow, Batch, TokenUsage } from '../types'
import { totalTokens } from './pricing'

type SpawnFacts = {
  id: string
  description: string
  agentType: string
  agentName: string | null
  isNested: boolean
  startedAt: number
}
type FinishReason = 'answer' | 'aborted' | 'error' | 'refusal'
type ListedAgent = { id: string; description: string; status: string; type: string; parentId?: string; teammateId?: string }

const FAILURE_REASONS: Record<Exclude<FinishReason, 'answer'>, string> = {
  aborted: '已中斷',
  error: 'API 錯誤',
  refusal: '模型拒絕',
}

const THINKING_ACTIVITY = '思考中'

// $.agent.list() 裡這一輪還沒結束、之後會收到 turn.complete 的狀態：還沒開始、正在跑、等權限或背景工作。
// idle 是這一輪已結束、等訊息喚醒（teammate），補成 running 會一直收不到結束而卡住，所以不算
const LIVE_STATUSES: ReadonlySet<string> = new Set(['pending', 'running', 'waiting'])

// 還沒有任何動作，目前動作的開始時間先用派出時間
function newRow(spawn: SpawnFacts, look: number): AgentRow {
  return {
    ...spawn,
    status: 'running',
    endedAt: null,
    failureReason: null,
    model: null,
    effort: null,
    toolCount: 0,
    activity: '',
    activityStartedAt: spawn.startedAt,
    lastUsage: null,
    reportedTokens: null,
    look,
  }
}

// host 保存的批次可能有舊版記下、沒有 look 的列：當成第一種造型，畫面不會壞，配號時也算 0 已被用掉
export function agentLook(row: AgentRow): number {
  return row.look ?? 0
}

// 造型依派出順序輪流：挑這一批還沒用掉的最小號碼。跨回合還在跑的保留原本的造型，新派的不會跟它撞；
// 完成後被新批次清掉的號碼可以再用，號碼才不會越跳越大（超過造型數時由 mascot.ts 取餘數）
function nextLook(agents: readonly AgentRow[]): number {
  const used = new Set(agents.map(agentLook))
  let look = 0
  while (used.has(look)) look += 1
  return look
}

// 新回合開新一批，帶過還在跑的（背景子代理可能跨回合）；turnId 不明（剛熱重載，模組變數歸零）時沿用現有批次
function batchForTurn(batch: Batch | null, currentTurnId: string | null): Batch {
  if (batch === null) return { turnId: currentTurnId ?? 'unknown', agents: [] }
  if (currentTurnId === null || batch.turnId === currentTurnId) return batch
  return { turnId: currentTurnId, agents: batch.agents.filter(agent => agent.status === 'running') }
}

function updateAgent(batch: Batch, agentId: string, change: (row: AgentRow) => AgentRow): Batch {
  const index = batch.agents.findIndex(agent => agent.id === agentId)
  if (index < 0) return batch
  const agents = batch.agents.slice()
  agents[index] = change(agents[index]!)
  return { ...batch, agents }
}

const finiteNumber = (value: unknown) => (typeof value === 'number' && Number.isFinite(value) ? value : null)

export function addAgent(batch: Batch | null, currentTurnId: string | null, spawn: SpawnFacts): Batch {
  const current = batchForTurn(batch, currentTurnId)
  if (current.agents.some(agent => agent.id === spawn.id)) return current
  return { ...current, agents: [...current.agents, newRow(spawn, nextLook(current.agents))] }
}

export function recordStep(
  batch: Batch,
  agentId: string,
  step: { model: string; effort?: string | number; usage: TokenUsage | null },
): Batch {
  return updateAgent(batch, agentId, row => {
    const withModel = { ...row, model: step.model, effort: step.effort ?? row.effort }
    // 請求失敗或中斷時沒有 usage：保留上一次的用量，不當成 0
    if (step.usage === null) return withModel
    return { ...withModel, lastUsage: step.usage }
  })
}

export function recordThinking(batch: Batch, agentId: string, at: number): Batch {
  return updateAgent(batch, agentId, row => ({ ...row, activity: THINKING_ACTIVITY, activityStartedAt: at }))
}

export function recordToolCall(batch: Batch, agentId: string, activity: string, at: number): Batch {
  return updateAgent(batch, agentId, row => ({ ...row, toolCount: row.toolCount + 1, activity, activityStartedAt: at }))
}

// 前景子代理完成時 Agent 工具結果帶的總計；背景子代理的結果沒有這兩個欄位，維持即時累計
export function recordReported(batch: Batch, agentId: string, reported: { totalTokens?: unknown; totalToolUseCount?: unknown }): Batch {
  const tokens = finiteNumber(reported.totalTokens)
  const toolUses = finiteNumber(reported.totalToolUseCount)
  if (tokens === null && toolUses === null) return batch
  return updateAgent(batch, agentId, row => ({
    ...row,
    reportedTokens: tokens ?? row.reportedTokens,
    toolCount: toolUses ?? row.toolCount,
  }))
}

// 不清掉 activity：失敗的卡片要用它顯示停在哪一步
export function finishAgent(batch: Batch, agentId: string, reason: FinishReason, endedAt: number): Batch {
  return updateAgent(batch, agentId, row =>
    reason === 'answer'
      ? { ...row, status: 'done', endedAt, failureReason: null }
      : { ...row, status: 'failed', endedAt, failureReason: FAILURE_REASONS[reason] },
  )
}

// 熱重載或面板開啟前就在跑的子代理：用 $.agent.list() 補上，用量從之後的請求開始累計。
// 清單沒有 Agent({ name }) 給的名字，所以 agentName 一律 null；teammate 跟派出時一樣不列入面板
export function seedRunning(batch: Batch | null, listed: readonly ListedAgent[], now: number): Batch | null {
  if (batch === null) return null
  const known = new Set(batch.agents.map(agent => agent.id))
  const missing = listed.filter(agent => agent.teammateId === undefined && LIVE_STATUSES.has(agent.status) && !known.has(agent.id))
  if (missing.length === 0) return batch
  // 一個一個加，後面的才看得到前面剛拿走的造型號碼
  const agents = missing.reduce<AgentRow[]>((rows, agent) => {
    const spawn = {
      id: agent.id,
      description: agent.description,
      agentType: agent.type,
      agentName: null,
      isNested: agent.parentId !== undefined,
      startedAt: now,
    }
    return [...rows, newRow(spawn, nextLook(rows))]
  }, batch.agents)
  return { ...batch, agents }
}

export function hasRunning(batch: Batch | null): boolean {
  return batch !== null && batch.agents.some(agent => agent.status === 'running')
}

export function agentTokens(row: AgentRow): number {
  if (row.reportedTokens !== null) return row.reportedTokens
  return row.lastUsage === null ? 0 : totalTokens(row.lastUsage)
}

// 時間從最早派出到最晚結束；還有在跑就算到現在
export function batchTotals(batch: Batch, now: number): { tokens: number; elapsedMs: number } {
  const { agents } = batch
  const tokens = agents.reduce((sum, agent) => sum + agentTokens(agent), 0)
  if (agents.length === 0) return { tokens, elapsedMs: 0 }
  const startedAt = Math.min(...agents.map(agent => agent.startedAt))
  const endedAt = hasRunning(batch) ? now : Math.max(...agents.map(agent => agent.endedAt ?? now))
  return { tokens, elapsedMs: Math.max(0, endedAt - startedAt) }
}

files.hooks/detail.ts:
// 子代理詳細頁的紀錄區：把一個子代理的紀錄排成一列一列帶顏色的文字片段。
// 每一列都先排進面板寬度，畫面截斷時也不會折行
import type { AgentLog, LogEntry, ToolOutcome } from '../types'
import { displayWidth, fitToWidth, formatElapsed } from './layout'
import type { Span } from './layout'
import { MAX_ENTRIES } from './log'

export const BACK_LABEL = '← 返回'

export type DetailOptions = { columns: number; now: number; startedAt: number }

type RowLayout = DetailOptions & { timeWidth: number }
type ToolEntry = Extract<LogEntry, { kind: 'tool' }>

const REPORT_LABEL = '回報'
const EMPTY_HINT = 'mod 載入前的紀錄沒有保留'
const MESSAGE_MAX_LINES = 3
const MESSAGE_CUT = '…」'
const TOOL_ICONS: Record<ToolOutcome, { icon: string; color?: string }> = {
  ok: { icon: '✓', color: 'success' },
  error: { icon: '✗', color: 'error' },
  denied: { icon: '⊘', color: 'warning' },
  running: { icon: '…' },
  unfinished: { icon: '·' },
}
// 子代理執行中面板每 0.2 秒重畫一次，回報最長幾百列：換行結果依（寬度、文字）快取，不每次重算。
// 一頁最多 MAX_ENTRIES 筆訊息或回報要換行，上限放得下一整頁；滿了丟最久沒用到的那筆（LRU），
// 紀錄滾動時只有新的那筆要算，不會整個清空重算
const WRAP_CACHE_LIMIT = MAX_ENTRIES
const wrapCache = new Map<string, string[]>()

export function formatOffset(ms: number): string {
  return `+${formatElapsed(ms)}`
}

// rows：紀錄區的每一列；newestRow：最新一筆的第一列在 rows 裡的位置（點開時捲到這裡），沒有紀錄是 -1
export type DetailLayout = { rows: Span[][]; newestRow: number }

export function detailLayout(log: AgentLog, options: DetailOptions): DetailLayout {
  if (log.entries.length === 0 && log.dropped === 0) return { rows: [[{ text: EMPTY_HINT, isDim: true }]], newestRow: -1 }
  const times = log.entries.map(entry => formatOffset(entry.at - options.startedAt))
  // 時間欄依最寬的對齊，續行才能對到同一欄
  const layout: RowLayout = { ...options, timeWidth: Math.max(0, ...times.map(displayWidth)) }
  const rows: Span[][] = log.dropped > 0 ? [[{ text: `更早的 ${log.dropped} 筆已省略`, isDim: true }]] : []
  let newestRow = -1
  log.entries.forEach((entry, index) => {
    newestRow = rows.length
    rows.push(...entryRows(entry, padTime(times[index] ?? '', layout.timeWidth), layout))
  })
  return { rows, newestRow }
}

export function detailRows(log: AgentLog, options: DetailOptions): Span[][] {
  return detailLayout(log, options).rows
}

// 依顯示寬度逐字硬切（中文 2 欄），'\n' 分段，空段落是空字串
export function wrapToWidth(text: string, width: number): string[] {
  return text.split('\n').flatMap(paragraph => wrapParagraph(paragraph, width))
}

function entryRows(entry: LogEntry, time: string, layout: RowLayout): Span[][] {
  if (entry.kind === 'tool') return toolRows(entry, time, layout)
  if (entry.kind === 'message') return messageRows(entry.text, time, layout)
  return reportRows(entry.text, time, layout)
}

// 時間、圖示、一行摘要；執行中的右邊是已經跑了多久，出錯或被拒絕時下一列寫原因
function toolRows(entry: ToolEntry, time: string, layout: RowLayout): Span[][] {
  const { icon, color } = TOOL_ICONS[entry.outcome]
  const isDim = entry.outcome === 'unfinished'
  const prefixWidth = layout.timeWidth + 3
  const elapsed = entry.outcome === 'running' ? formatElapsed(layout.now - entry.at) : ''
  const summaryWidth = layout.columns - prefixWidth - (elapsed === '' ? 0 : displayWidth(elapsed) + 1)
  const summary = fitToWidth(entry.summary, summaryWidth)
  const first: Span[] = [
    { text: time, isDim: true },
    { text: ' ', isDim },
    { text: icon, color, isDim },
    { text: ' ', isDim },
    { text: summary, isDim },
  ]
  if (elapsed !== '') {
    const gap = layout.columns - prefixWidth - displayWidth(summary) - displayWidth(elapsed)
    first.push({ text: ' '.repeat(Math.max(1, gap)) }, { text: elapsed })
  }
  const hasReason = entry.errorLine !== null && (entry.outcome === 'error' || entry.outcome === 'denied')
  if (!hasReason) return [first]
  // 原因列用淡色（淡紅、淡黃），跟上面那一列的圖示分出主次
  return [first, [{ text: ' '.repeat(prefixWidth) }, { text: fitToWidth(entry.errorLine ?? '', layout.columns - prefixWidth), color, isDim: true }]]
}

// 中途訊息：連續空白合成一個，包成「」後換行，最多 3 列，放不下時第 3 列結尾換成 …」
function messageRows(text: string, time: string, layout: RowLayout): Span[][] {
  const contentWidth = contentWidthOf(layout)
  const lines = wrapCached(`「${text.replace(/\s+/g, ' ').trim()}」`, contentWidth)
  const shown =
    lines.length > MESSAGE_MAX_LINES
      ? [...lines.slice(0, MESSAGE_MAX_LINES - 1), takeWidth(lines[MESSAGE_MAX_LINES - 1] ?? '', contentWidth - displayWidth(MESSAGE_CUT)) + MESSAGE_CUT]
      : lines
  const [head = '', ...rest] = shown
  return [[{ text: time, isDim: true }, { text: ' ' }, { text: head }], ...rest.map(line => continuationRow(line, layout))]
}

// 回報：一列標題，下面照原本的段落完整換行（空行保留）
function reportRows(text: string, time: string, layout: RowLayout): Span[][] {
  const normalized = text.replace(/\r\n?/g, '\n').replace(/\t/g, '  ')
  const body = wrapCached(normalized, contentWidthOf(layout)).map(line => continuationRow(line, layout))
  return [[{ text: time, isDim: true }, { text: ' ' }, { text: REPORT_LABEL, isBold: true }], ...body]
}

function continuationRow(line: string, layout: RowLayout): Span[] {
  return [{ text: ' '.repeat(layout.timeWidth + 1) }, { text: line }]
}

function contentWidthOf(layout: RowLayout) {
  return layout.columns - layout.timeWidth - 1
}

function padTime(time: string, timeWidth: number) {
  return time + ' '.repeat(Math.max(0, timeWidth - displayWidth(time)))
}

// 回傳的陣列跟快取共用，呼叫端不能改它。Map 依加入順序排：用到就移到最後，最前面就是最久沒用到的
export function wrapCached(text: string, width: number): string[] {
  const key = `${width}|${text}`
  const cached = wrapCache.get(key)
  if (cached !== undefined) {
    wrapCache.delete(key)
    wrapCache.set(key, cached)
    return cached
  }
  if (wrapCache.size >= WRAP_CACHE_LIMIT) {
    const oldest = wrapCache.keys().next()
    if (oldest.done !== true) wrapCache.delete(oldest.value)
  }
  const lines = wrapToWidth(text, width)
  wrapCache.set(key, lines)
  return lines
}

// 連續的英數字與半形符號（不含空白）是一個詞，連續空白是一段，其他字元（中文、全形標點、emoji）各自一段
const WRAP_TOKEN = /[!-~]+| +|[^]/gu

// 英數字的詞放不下就整個換到下一列，比一列還長才硬切；換行後的開頭不留空白，段落本身開頭的縮排保留
function wrapParagraph(paragraph: string, width: number): string[] {
  if (paragraph === '') return ['']
  const lines: string[] = []
  let line = ''
  let lineWidth = 0
  const breakLine = () => {
    lines.push(line.replace(/ +$/, ''))
    line = ''
    lineWidth = 0
  }
  // 一列至少放一個字，寬度比字還窄時也不會無限迴圈
  const putChar = (char: string) => {
    const charWidth = displayWidth(char)
    if (lineWidth + charWidth > width && line !== '') breakLine()
    line += char
    lineWidth += charWidth
  }
  for (const token of paragraph.match(WRAP_TOKEN) ?? []) {
    const tokenWidth = displayWidth(token)
    if (token.startsWith(' ')) {
      // 換行後的開頭不放空白；放不下的空白直接換行
      if (line === '' && lines.length > 0) continue
      if (lineWidth + tokenWidth > width) breakLine()
      else {
        line += token
        lineWidth += tokenWidth
      }
    } else if (token.length > 1 && lineWidth + tokenWidth > width && tokenWidth <= width) {
      // 英數字的詞放不下，但一列放得下：整個換到下一列
      breakLine()
      line = token
      lineWidth = tokenWidth
    } else {
      for (const char of token) putChar(char)
    }
  }
  lines.push(line.replace(/ +$/, ''))
  return lines
}

// 取開頭不超過 width 欄的部分，不補「…」
function takeWidth(text: string, width: number): string {
  let kept = ''
  let keptWidth = 0
  for (const char of text) {
    const charWidth = displayWidth(char)
    if (keptWidth + charWidth > width) break
    kept += char
    keptWidth += charWidth
  }
  return kept
}

